#include "optimizer.h"
#include <string.h>
void scenario(Plan *p,int kind){int i,n,orders;unsigned int seed=42;memset(p,0,sizeof(*p));n=(kind==2)?120:(kind==3?20:6);orders=(kind==2)?700:(kind==3?80:6);network_init(&p->network,n);p->capacity=(kind==1)?5:(kind==2?500:(kind==3?40:12));for(i=0;i<n-1;i++)road_add(&p->network,i,i+1,2);for(i=0;i<n-5;i++)road_add(&p->network,i,i+5,7);if(kind==0||kind==1){int weights[]={2,3,4,2,5,1},values[]={120,150,180,100,220,80},priorities[]={5,4,3,5,2,5};for(i=0;i<6;i++){Order o={101+i,(i+1)%n,weights[i],priorities[i],values[i]};order_add(p,o);}}else for(i=0;i<orders;i++){Order o;seed=seed*1664525u+1013904223u;o.id=i+1;o.destination=(int)(seed%(unsigned)n);seed=seed*1664525u+1013904223u;o.weight=1+(int)(seed%10u);seed=seed*1664525u+1013904223u;o.value=50+(int)(seed%500u);o.priority=(kind==3)?3:1+(i%5);order_add(p,o);}}
